actions.script:
const L = (text) => ec.l10n.localize(text)
// the holders a conflict can name: on an all-in-one node the server itself too
conflictsText = allInOne
    ? L('Records a local node replicated that claim an item another owner holds: a mail address, a chat bridge or a phone number this server holds itself, or one another local node claimed first. The holder wins, and the record is not applied until the holder lets the item go; remove it on one side.')
    : L('Records a local node replicated that claim a mail address or a phone number another local node claimed first. The first claim wins, and the record is not applied until that node lets the item go; remove it on one side.')
hostList = []
domainList = []
conflictList = []
nodeOptions = []
domainsError = ''
memoryError = ''
if (!isEdge) return
let hostsOut = {}
let domainsOut = {}
let conflictsOut = {}
let balancingOut = {}
ec.message.pushErrors()
try {
    hostsOut = ec.service.sync().name('org.moqui.edge.EdgeServices.get#EdgeHosts').call() || {}
    if (!ec.message.hasError()) domainsOut = ec.service.sync().name('org.moqui.edge.EdgeServices.get#EdgeDomains').call() || {}
    if (!ec.message.hasError()) conflictsOut = ec.service.sync().name('org.moqui.edge.EdgeServices.get#ReplicaConflicts').call() || {}
    if (ec.message.hasError()) domainsError = ec.message.getErrorsString()
} finally {
    ec.message.clearErrors()
    ec.message.popErrors()
}
if (domainsError) return
// what is kept in memory, in a probe of its own: a failure there leaves the rows shown
const probe = (name) => {
    ec.message.pushErrors()
    try {
        const answer = ec.service.sync().name('org.moqui.edge.EdgeServices.' + name).call() || {}
        if (!ec.message.hasError()) return answer
        memoryError = ec.message.getErrorsString()
        return {}
    } finally {
        ec.message.clearErrors()
        ec.message.popErrors()
    }
}
balancingOut = probe('get#EdgeBalancing')
const join = (items) => Array.from(items || []).join(', ')
// the edge conf's sticky-cookie, which a terminate host without its own uses
const stickyDefault = balancingOut.stickyCookie || 'moqui.session'
hostList = Array.from(hostsOut.hostList || []).map((host) => {
    const terminate = host.modeEnumId === 'EdgeHostTerminate'
    return {hostName: host.hostName, nodeId: host.pairedNodeId, modeEnumId: host.modeEnumId,
        hostKey: String(host.hostName).replace(/[^A-Za-z0-9]/g, '_'), terminate,
        cookieValue: host.stickyCookie || '',
        cookieText: !terminate ? L('By client address') : host.stickyCookie || L('The conf\'s') + ' (' + stickyDefault + ')',
        modeLabel: terminate ? L('Terminate') : L('Passthrough'), modeColor: terminate ? 'warning' : 'positive'}
})
domainList = Array.from(domainsOut.domainList || []).map((domain) => ({
    nodeId: domain.pairedNodeId,
    mailText: join(domain.mailDomains),
    xmppDomain: domain.xmppDomain || '',
    sipText: [domain.sipDomain || '', join(domain.phoneNumbers) + (domain.phoneNumbersCut ? ', ' + L('and more not shown') : '')]
        .filter((part) => part).join(' · '),
    chatText: join(domain.chatBridgeIds),
    passText: join(domain.passSites),
    setupText: domain.setupDate ? ec.l10n.format(domain.setupDate, '') : L('Not yet')}))
nodeOptions = domainList.map((domain) => ({nodeId: domain.nodeId}))
conflictList = Array.from(conflictsOut.conflictList || []).map((conflict) => ({
    nodeId: conflict.pairedNodeId, setName: conflict.setName,
    itemText: (conflict.claimLabel || '') + ' ' + (conflict.itemKey || ''),
    ownerText: conflict.ownerText || '',
    lastText: conflict.lastDate ? ec.l10n.format(conflict.lastDate, '') : ''}))
